-- A/B Test dummy data (Online gaming) - France - 1 month
-- Target: Microsoft SQL Server (older versions) - uses DATETIME (no TIMESTAMP columns)

SET NOCOUNT ON;

IF OBJECT_ID('dbo.ab_test_welcome_offer_fr','U') IS NOT NULL
    DROP TABLE dbo.ab_test_welcome_offer_fr;
GO

CREATE TABLE dbo.ab_test_welcome_offer_fr (
    userid                 VARCHAR(50) NOT NULL PRIMARY KEY,
    test_country           CHAR(2)      NOT NULL CONSTRAINT DF_ab_test_country DEFAULT ('FR'),
    test_group             CHAR(1)      NOT NULL CONSTRAINT CK_ab_test_group CHECK (test_group IN ('A','B')),

    -- Core outcomes
    converted              INT          NOT NULL CONSTRAINT CK_ab_converted CHECK (converted IN (0,1)),
    welcome_bonus_opted_in INT          NOT NULL CONSTRAINT CK_ab_bonusopt CHECK (welcome_bonus_opted_in IN (0,1)),

    -- Attribution / dimensions
    channel                VARCHAR(50)  NOT NULL,
    campaign               VARCHAR(80)  NULL,
    device_type            VARCHAR(20)  NOT NULL,
    os                     VARCHAR(30)  NOT NULL,
    landing_variant        VARCHAR(30)  NOT NULL,     -- Control / Test (A/B UI)
    assigned_at            DATETIME     NOT NULL,     -- proxy for first seen + assignment

    -- Funnel timestamps (use DATETIME; avoid SQL Server TIMESTAMP/ROWVERSION confusion)
    conversion_dt          DATETIME     NULL,
    first_deposit_dt       DATETIME     NULL,

    -- Post-conversion metrics (first 30 days after conversion; illustrative)
    deposits_count_30d     INT           NOT NULL CONSTRAINT DF_ab_depcount DEFAULT (0),
    total_deposit_30d      DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_totaldep DEFAULT (0),
    total_withdrawal_30d   DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_totalwd  DEFAULT (0),
    bonus_issued_30d       DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_bonusiss DEFAULT (0),
    bonus_cost_30d         DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_bonuscst DEFAULT (0),
    bet_amount_30d         DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_betamt   DEFAULT (0),
    gross_gaming_rev_30d   DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_ggr      DEFAULT (0),
    net_gaming_rev_30d     DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_ngr      DEFAULT (0),
    payment_fees_30d       DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_fees     DEFAULT (0),
    chargeback_amt_30d     DECIMAL(12,2) NOT NULL CONSTRAINT DF_ab_cb       DEFAULT (0),

    -- Engagement
    sessions_30d           INT           NOT NULL CONSTRAINT DF_ab_sess     DEFAULT (0),
    active_days_30d        INT           NOT NULL CONSTRAINT DF_ab_actdays  DEFAULT (0),
    retention_d7           INT           NOT NULL CONSTRAINT DF_ab_r7       DEFAULT (0) CONSTRAINT CK_ab_r7 CHECK (retention_d7 IN (0,1)),
    retention_d30          INT           NOT NULL CONSTRAINT DF_ab_r30      DEFAULT (0) CONSTRAINT CK_ab_r30 CHECK (retention_d30 IN (0,1))
);
GO

CREATE INDEX IX_ab_test_group   ON dbo.ab_test_welcome_offer_fr(test_group);
CREATE INDEX IX_ab_test_channel ON dbo.ab_test_welcome_offer_fr(channel);
CREATE INDEX IX_ab_test_convdt  ON dbo.ab_test_welcome_offer_fr(conversion_dt);
GO

